data class McRequest(
    val id: String,
    val command: RemoteCommand,
    val expected: Expected? = null,
)

sealed interface McResult<out T> {
    data class Success<T>(
        val value: T,
    ) : McResult<T>

    data class Failure(
        val error: McError,
    ) : McResult<Nothing>
}
typealias McError = ErrorPayload

sealed interface McReply {
    val id: String

    data class Success(
        override val id: String,
        val result: RemoteResult,
    ) : McReply

    data class Failure(
        override val id: String,
        val error: McError,
    ) : McReply
}

